"""Exam reading lists: exact codifier scope and clearly labelled workshop routes."""
import json
from pathlib import Path
from html import escape as e
from school_data import load_grades
from quote_sources import quote_block
from reading_list_extras import EXTRAS

ROOT='/chtenie/'
DATE='2 октября 2026 года'
EGE='https://fipi.ru/ege/demoversii-specifikacii-kodifikatory'
OGE='https://fipi.ru/oge/demoversii-specifikacii-kodifikatory'
ITOG='https://fipi.ru/itogovoe-sochinenie'
STRUCTURE='https://doc.fipi.ru/itogovoe-sochinenie/2026/01_Struktura_banka_tem_sochineniy.pdf'
# The landing-page link below is authoritative; filenames are never inferred for readers.
SECTIONS=[('oge-literatura','ОГЭ по литературе','48 позиций кодификатора'),('ege-literatura','ЕГЭ по литературе','66 позиций: ОШ1–ОШ10 и 1–56'),('russkiy-yazyk','Русский язык: ОГЭ и ЕГЭ','Чтение для анализа и аргументации'),('itogovoe','Итоговое сочинение','Подборки к 11 тематическим подразделам'),('sobesedovanie','Итоговое собеседование','Чтение вслух, понимание, монолог'),('drugie-formy','Другие формы работы','Дневник, рецензия, дискуссия и проект'),('dopolneniya','Дополнение к школьному курсу','Семь произведений и направлений чтения')]

def unit(ref):
 n,i=map(int,ref.split('-'));return load_grades()[n]['units'][i-1]
def url(ref):
 if ref.startswith('x-'):return ROOT+'dopolneniya/#'+ref[2:]
 n,i=map(int,ref.split('-'));return f'/shkola/{n}/unit-{i:02d}/'
def link(ref,label=None):
 if label is None:
  label=next(x['title'] for x in EXTRAS if 'x-'+x['id']==ref) if ref.startswith('x-') else unit(ref)['title']
 return f'<a href="{url(ref)}">{e(label)}</a>'
def nav():
 return '<nav class="reading-list-nav" aria-label="Списки чтения"><a href="/chtenie/tolstoy-kavkaz/">Толстой: Кавказ</a><a href="/chtenie/vneklassnoe/">Внеклассное чтение 1–11</a><a href="/chtenie/iz-uchebnikov/">Списки из учебников</a>'+''.join(f'<a href="{ROOT}{s}/">{e(t)}</a>' for s,t,_ in SECTIONS)+'</nav>'
def shell(title,lead,body):
 return f'<div class="wrap"><div class="breadcrumb"><a href="/">Главная</a><span>/</span><a href="{ROOT}">Что читать</a></div><header class="page-title"><p class="eyebrow">Библиотека читательских маршрутов</p><h1>{e(title)}</h1><p class="lead">{e(lead)}</p></header>{nav()}<article class="prose reading-lists">{body}</article></div>'
def paragraphs(items):return ''.join('<p>'+e(p)+'</p>' for p in items)
def route_links(refs):return '<ul>'+''.join('<li>'+link(r)+'</li>' for r in refs)+'</ul>'
def spiritual():
 return '<section><h2>Читаем в диалоге с православной мыслью</h2>'+quote_block('vnimanie')+'<p><strong>Комментарий мастерской.</strong> Здесь речь источника относится к молитве. Мы сопоставляем её с читательским вниманием, не приписывая духовному автору советов по экзамену. Сначала нужно услышать текст, затем — сформулировать собственную оценку. Святоотеческая цитата не заменяет литературного примера и не делает необязательным ответ на вопрос задания.</p><p>В связанных разборах духовные цитаты и имена авторов ведут прямо на biblioteka3.ru. Наше толкование отделено от источника. Согласие с религиозной позицией не оценивается.</p></section>'

def codifier(kind):
 data=json.loads(Path(__file__).with_name('reading_lists_data.json').read_text())[kind]
 exam='ЕГЭ' if kind=='ege' else 'ОГЭ'
 source=EGE if kind=='ege' else OGE
 zipurl=f'https://doc.fipi.ru/{kind}/demoversii-specifikacii-kodifikatory/2027/li_{11 if kind=="ege" else 9}_2027.zip'
 body=f'<div class="context-note"><strong>Основание списка:</strong> проект кодификатора ФИПИ {exam} 2027 года, таблица 3. Проверено {DATE}. <a href="{source}">Официальная страница</a> · <a href="{zipurl}">Комплект документов, ZIP</a>. Статус проекта сохранён: окончательную редакцию нужно сверять перед экзаменом.</div>'
 body+='<p>Ниже приведены все позиции таблицы 3. Номер относится к позиции документа, а не к числу книг. Указанные ФИПИ названия и авторские группы отделены от наших советов. В открытых группах «и другие» сохраняет возможность выбора; это не указание прочитать собрания сочинений всех авторов.</p>'
 if kind=='ege':
  body+='<h2>Как понимать этот перечень</h2><p>ОШ1–ОШ10 — материал основной школы. Он остаётся важен для сопоставлений и сочинения, хотя фрагменты восьми названных эпических и драматических произведений не служат исходными текстами первой части. Для основной группы 1–56 способы использования произведений также различаются; полный перечень сам по себе не означает, что любое название станет темой отдельного сочинения.</p><p>Открытые группы с кодами 20, 39, 40, 52–56 дают материал для самостоятельного выбора, когда формулировка задания это допускает. По авторам этих групп отдельные именные темы не формулируются. Полужирная маркировка исходного документа выделяет произведения для первой части; за её полными правилами обращайтесь к пояснениям кодификатора на страницах 12–13.</p><p><strong>БУ</strong> — базовый уровень школьной программы, <strong>УУ</strong> — углублённый. Это характеристика программы в документе, а не два разных экзамена по литературе. Позиции только с УУ отмечены отдельно. Школьный разбор нескольких глав не заменяет чтение целого романа, если перечень не ограничивает объём.</p>'
 else:
  body+='<h2>Что важно в формулировках</h2><p>«Одно произведение по выбору» и несколько перечисленных названий — разные требования. У Толстого названы «После бала» и ещё одно произведение. У Салтыкова-Щедрина перечислены три сказки. Наши школьные занятия иногда начинают с меньшей выборки: здесь это отмечено.</p><p>Список поэтов открыт: для анализа может встретиться незнакомое стихотворение. Подготовка поэтому включает и знание прочитанного, и умение самостоятельно объяснять образы, композицию, интонацию. Возрастные указания ниже перенесены из кодификатора; расположение темы в нашем курсе может отличаться.</p>'
 body+='<details class="list-index"><summary>Все авторы и позиции</summary><ol>'+''.join(f'<li><a href="#code-{r["code"]}">{e(r["code"])}. {e(r["text"])}</a></li>' for r in data)+'</ol></details>'
 for r in data:
  refs=r['routes']; normal=[x for x in refs if not x.startswith('x-')]
  scope=('Только УУ' if r['level']=='УУ' else r['level']) if kind=='ege' else r['level']+' класс по кодификатору'
  focus=r['focus'] or unit(normal[0])['analysis']
  # The exact official text comes first. Workshop selections never replace it.
  selection=''
  if normal:
   selections=list(dict.fromkeys(unit(x)['reading'] for x in normal))
   selection='<details><summary>Что уже разбираем в связанном курсе</summary>'+paragraphs(selections)+'<p class="fine">Это содержание связанных занятий. Оно не добавляет и не отменяет требований позиции ФИПИ; отдельный разбор каждого текста открытой группы здесь не заявляется.</p></details>'
  body+=f'<section class="reading-list-entry" id="code-{r["code"]}"><p class="eyebrow">Код {e(r["code"])} · {e(scope)}</p><h2>{e(r["text"])}</h2><h3>Как работать с этой позицией</h3><p>{e(focus)}</p>{selection}<h3>Разборы и читательские вопросы</h3>{route_links(refs)}</section>'
 body+=spiritual()+f'<p><a href="/k-sochineniyu/{kind}-literatura/">Практика письменного ответа: {exam} по литературе</a></p>'
 return body

# The thematic headings follow FIPI's structure; books and connections are editorial selections.
THEMES=[
('1.1','Внутренний мир человека и его личностные качества',['10-3','10-12','7-17'],'«Обломов»; «Ионыч», «Человек в футляре»; «Юшка».','Сопоставьте качество, которое герой приписывает себе, с тем, что видят другие. Как меняется человек в книге? Ответ на этот вопрос скажет о нём больше, чем одно слово «добрый» или «гордый».','Почему доброго намерения иногда недостаточно?','Не превращайте бедность или болезнь в нравственную характеристику.'),
('1.2','Отношение человека к другому человеку (окружению), нравственные идеалы и выбор между добром и злом',['6-12','8-4','6-15'],'«Чудесный доктор»; «Капитанская дочка»; «Уроки французского».','Выберите конкретный поступок помощи. Установите, что он меняет для получателя и чем рискует помогающий. Сопоставление раскроет разные формы милосердия, не сводя их к размеру пожертвования.','Может ли милосердие сочетаться с твёрдостью убеждений?','Не выдавайте нарушение любого правила за добро: исследуйте обстоятельства и последствия.'),
('1.3','Познание человеком самого себя',['9-11','10-9','7-8'],'«Герой нашего времени»; «Преступление и наказание»; «После бала».','Поставьте рядом момент самообъяснения и событие, которое ему противоречит. Так можно доказать, что познание себя не всегда начинается с желания нравственно измениться.','Всегда ли человек способен верно судить о себе?','Самоанализ Печорина не равен раскаянию, а сильное впечатление ещё не доказывает устойчивой перемены.'),
('1.4','Свобода человека и её ограничения',['8-5','x-my','10-2'],'«Мцыри»; «Мы»; «Гроза».','Различите внешнее принуждение, внутренний страх и добровольно принятую ответственность. Во всех книгах есть несвобода, но она устроена по-разному.','Где проходит граница между заботой и подавлением?','Не сводите свободу к отсутствию любой связи с другими людьми.'),
('2.1','Семья, род; семейные ценности и традиции',['10-4','10-10','8-10'],'«Отцы и дети»; «Война и мир»; «Лето Господне».','Семейная близость проявляется в повседневных действиях, памяти, несогласии и попытке понять. Для аргумента выберите одну сцену, а не перечень фамилий семей.','Что помогает сохранить близость при разнице убеждений?','Не объявляйте литературное изображение одной семьи правилом для всех семей.'),
('2.2','Человек и общество',['9-5','8-6','8-15'],'«Горе от ума»; «Шинель»; «Матрёнин двор».','По чему здесь судят о человеке: по слухам, чину, достатку, удобству для окружающих? Объясните, почему окружающие замечают одни качества человека и пропускают другие.','Может ли общественное мнение ошибаться в оценке человека?','Противостояние обществу само по себе не делает героя правым.'),
('2.3','Родина, государство, гражданская позиция человека',['10-10','8-14','x-po-pravu-pamyati'],'«Война и мир»; «Судьба человека»; «По праву памяти».','Сопоставьте личный выбор с большой историей. В исторической теме сначала уточните событие и обстоятельства, затем объясняйте позицию героя или автора. Художественная сцена показывает смысл, но не заменяет исторический документ.','В чём может выражаться ответственность перед памятью прошлого?','Не отождествляйте любовь к людям и стране с безусловным одобрением любого властного решения.'),
('3.1','Природа и человек',['5-14','6-7','11-24'],'«Васюткино озеро»; лирика Тютчева и Фета; «Прощание с Матёрой».','Различайте природу как среду выживания, собеседника лирического героя и место общей памяти. Укажите, что именно связывает человека с окружающим миром в выбранном тексте.','Почему отношение к природе раскрывает отношение человека к жизни?','У природы в произведении не всегда есть функция нравственного судьи.'),
('3.2','Наука и человек',['8-12','x-my','11-30'],'«Собачье сердце»; «Мы»; «451 градус по Фаренгейту».','Разделите научное знание, техническое средство и решение о его применении. Фантастический эксперимент помогает поставить этический вопрос, но не служит эмпирическим доказательством о реальной науке.','Снимает ли техническая возможность вопрос о допустимости поступка?','Физическая формула не доказывает нравственный тезис; математическая модель требует явных предпосылок.'),
('3.3','Искусство и человек',['8-3','10-12','11-30'],'«Моцарт и Сальери»; «Студент»; «451 градус по Фаренгейту».','Можно исследовать зависть к дару, силу рассказанной истории и сопротивление культурному забвению. Выберите один механизм воздействия искусства и докажите его эпизодом.','Почему художественное слово способно изменить взгляд на жизнь?','Картина и музыка могут дополнить рассуждение, но в итоговом сочинении необходим литературный материал.'),
('3.4','Язык и языковая личность',['7-7','9-5','11-15'],'«Русский язык» Тургенева; «Горе от ума»; «Возвращение» Платонова.','Покажите связь речи и отношения к миру: точность слова, готовый ярлык, попытку услышать другого. Язык характеризует не только образованность, но и способ обращения с человеком.','Почему ответственность за слово является нравственной ответственностью?','Не оценивайте героя только по правильности речи: важны её цель, адресат и воздействие.'),
]

def final_list():
 body=f'<div class="context-note">Итоговое сочинение, 2026/27. <a href="{STRUCTURE}">Официальная структура банка тем</a> и <a href="{ITOG}">критерии и рекомендации ФИПИ</a>. Книги ниже подобраны мастерской: это не обязательный список ФИПИ и не прогноз декабрьских тем.</div>'
 body+='<p>В итоговом сочинении можно опираться на художественную и другую опубликованную литературу, в том числе документальную, научно-популярную и философскую. По критерию литературной аргументации достаточно одного текста, если он действительно помогает раскрыть тему. Упоминание названия без разбора примера не выполняет эту задачу.</p><p>Ниже — все 11 подразделов официальной структуры. Формулировки вопросов и подбор произведений принадлежат мастерской. Один текст может пригодиться в нескольких подразделах, но готовый аргумент придётся каждый раз заново связать с конкретным вопросом.</p>'
 for code,title,refs,books,analysis,question,limit in THEMES:
  body+=f'<section class="reading-list-entry" id="theme-{code.replace(".","-")}"><p class="eyebrow">Подраздел {code}</p><h2>{e(title)}</h2><p><strong>Предлагаем читать:</strong> {e(books)}</p><p>{e(analysis)}</p><p><strong>Учебный вопрос:</strong> {e(question)}</p><p><strong>Граница аргумента:</strong> {e(limit)}</p>{route_links(refs)}</section>'
 body+='<section><h2>Дополнительная публицистика: Д. С. Лихачёв</h2><p>В «Письмах о добром и прекрасном» предлагаем начать с пятого письма о смысле жизни и шестого о цели и самооценке. Сопоставьте тезис, пример и вопрос к читателю. Напишите ответ: с чем вы согласны и где хотели бы уточнить обобщение? Это самостоятельная рекомендация мастерской, а не позиция обязательного экзаменационного перечня.</p><p><a href="https://books.yandex.ru/books/TKEcQENY/read-online">Открыть доступный фрагмент книги</a>. Содержание фрагмента не выдаётся за полный текст издания.</p></section>'
 body+='<h2>От книги к аргументу</h2><ol><li>Запишите точный вопрос темы и свой ответ одним предложением.</li><li>Выберите эпизод, в котором проверяется именно эта мысль.</li><li>Назовите поступок, обстоятельства и результат.</li><li>Объясните, почему пример поддерживает ваш вывод и чего он не доказывает.</li><li>Проверьте имена, названия и последовательность событий по тексту.</li></ol><p>Не заучивайте готовое сочинение: самостоятельность — отдельное требование. Цитата из духовного источника может стать предметом рассуждения, но сама по себе не заменяет осмысленной литературной опоры.</p>'
 body+=spiritual()+'<p><a href="/k-sochineniyu/itogovoe/">Развёрнутый учебный пример и поле для своего сочинения</a> · <a href="/filosofiya/">Философские статьи</a></p>'
 return body

RUSSIAN=[
('6-12','А. Куприн. «Чудесный доктор»','Конкретная помощь и достоинство','Найдите два разных действия доктора. Объясните вклад каждого в перемену положения семьи; не повторяйте одно общее слово «доброта».','Для собственного аргумента можно показать, что участие требует действия и внимания к обстоятельствам.'),
('7-17','А. Платонов. «Юшка»','Уязвимость и общественная жестокость','Сопоставьте отношение окружающих с тем, что становится известно о Юшке. Объясните роль позднего узнавания.','Пример помогает спорить с оценкой человека по видимости, но не оправдывает терпимость к насилию.'),
('6-15','В. Распутин. «Уроки французского»','Помощь, стыд и самостоятельность','Выберите две неудачные или удачные попытки помощи. Уточните, почему одна форма вызывает отказ, а другая допускает принятие.','Аргумент требует различить намерение учителя, правила учреждения и конкретную нужду ребёнка.'),
('7-12','А. Чехов. «Тоска»','Умение слушать','Выделите две попытки Ионы рассказать о потере. Объясните, что повторяется и как нарастает ощущение одиночества.','Важно доказать именно потребность быть услышанным, а не просто пересказать несчастье.'),
('8-14','М. Шолохов. «Судьба человека»','Память и возобновление заботы','Сопоставьте историю потерь с решением взять ответственность за Ванюшку. Не называйте второй эпизод отменой первого.','Пример раскрывает деятельную связь с другим человеком после пережитой катастрофы.'),
('8-4','А. Пушкин. «Капитанская дочка»','Милосердие и верность','Найдите поступок благодарности и отказ от нравственной уступки. Объясните, почему они не обязательно противоречат друг другу.','Не сводите роман к правилу, будто добро всегда получает немедленное вознаграждение.'),
('7-8','Л. Толстой. «После бала»','Перемена взгляда','Сопоставьте портрет полковника на балу и утром. Покажите роль композиционного контраста и деталей.','Можно рассуждать о том, как увиденное разрушает удобную оценку человека.'),
('5-14','В. Астафьев. «Васюткино озеро»','Знание и действие','Выделите момент ошибки и способ исправления положения. Объясните различие паники, наблюдения и применения опыта.','Литературная ситуация подтверждает роль знаний, но не обещает успех при любых обстоятельствах.'),
('10-12','А. Чехов. «Студент»','Связь времён и сила рассказа','Проследите перемену состояния Ивана Великопольского и реакцию слушательниц. Укажите, чья оценка мира выражена в финале.','Не превращайте заключение героя в единственно допустимый авторский философский тезис.'),
('8-15','А. Солженицын. «Матрёнин двор»','Незаметное добро','Выберите деталь повседневной помощи и оценку окружающих. Объясните расхождение двух мерок человеческой ценности.','Аргумент о бескорыстии не должен делать эксплуатацию помогающего нормой.'),
('8-10','И. Шмелёв. «Лето Господне»','Семейная и культурная память','Разберите один прочитанный эпизод: какие запахи, звуки, действия взрослых сохраняет детская память?','Используйте только действительно прочитанную главу, сохраняя различие детского взгляда и взрослого воспоминания.'),
('x-rozhdestvo','В. Набоков. «Рождество»','Горе и возможность надежды','Сопоставьте предметные детали до финала с появлением живой бабочки. Объясните связь, не добавляя нерассказанного продолжения.','Финал не доказывает, что человеку достаточно приказать себе перестать горевать.'),
]

def russian_list():
 body=f'<div class="context-note">Это наша рекомендательная подборка, не официальный обязательный список книг по русскому языку. Основание правил работы: проекты ФИПИ 2027 года — <a href="{OGE}">ОГЭ</a> и <a href="{EGE}">ЕГЭ</a>. Сверено {DATE}.</div>'
 body+='<h2>Две разные задачи чтения</h2><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Форма</th><th>Откуда брать материал</th><th>Зачем нужны книги ниже</th></tr></thead><tbody><tr><th>ОГЭ: изложение</th><td>Из прослушанного текста. Сохраняем его содержание, не добавляем свою позицию.</td><td>Тренировать выделение микротем и сжатие на учебных фрагментах.</td></tr><tr><th>ОГЭ: сочинение</th><td>В проекте 2027 года два примера берутся из выданного текста и поясняются.</td><td>Учиться замечать детали и объяснять примеры; на экзамене знакомая книга не заменяет исходный текст.</td></tr><tr><th>ЕГЭ: сочинение</th><td>Комментарий — по исходному тексту; собственное отношение подкрепляется отдельным аргументом.</td><td>Расширять читательский опыт для собственной аргументации. Допускаемый опыт не ограничивается литературой.</td></tr></tbody></table></div><p>Все задания в карточках ниже — учебные. При работе по формату ОГЭ или ЕГЭ сначала выберите конкретный фрагмент и сформулируйте вопрос к нему. На реальном экзамене ориентируйтесь на выданный текст и инструкцию.</p>'
 for ref,title,theme,exercise,argument in RUSSIAN:
  body+=f'<section class="reading-list-entry"><p class="eyebrow">{e(theme)}</p><h2>{e(title)}</h2><p><strong>Тренируем анализ:</strong> {e(exercise)}</p><p><strong>Возможность собственного аргумента:</strong> {e(argument)}</p><p>{link(ref,"Открыть разбор и вопросы к чтению")}</p></section>'
 body+=spiritual()+'<p><a href="/k-sochineniyu/oge-russkiy/">ОГЭ: изложение и сочинение</a> · <a href="/k-sochineniyu/ege-russkiy/">ЕГЭ: комментарий и собственная позиция</a></p>'
 return body

def oral_list():
 body='<div class="context-note">Официального списка художественных книг для допуска к собеседованию нет. Ниже — тренировочное чтение мастерской. <a href="https://fipi.ru/itogovoye-sobesedovaniye">Проект формата и демоверсия ФИПИ 2027 года</a> проверены 2 октября 2026 года.</div><p>Первым материалом для знакомства с форматом должна быть официальная демоверсия: чтение текста вслух, беседа по нему и монолог. Для подготовки полезны также биографические и научно-популярные тексты, музейные описания. В них нужно различать факт, оценку и объяснение. Художественное чтение ниже развивает те же речевые умения, но не прогнозирует содержание экзамена.</p>'
 items=[('5-14','Событие и последовательность','Выберите эпизод из «Васюткина озера». Подготовьте устный рассказ: обстоятельства, затруднение, решение, результат. Ответьте, на каких признаках герой основывает вывод.'),('6-12','Поступок и его объяснение','По «Чудесному доктору» подготовьте ответы на вопросы: что произошло, кому нужна помощь, что сделал герой, почему это важно, какую деталь нельзя опустить?'),('7-12','Интонация и подтекст','Прочитайте небольшой фрагмент «Тоски» вслух. Отметьте паузы и смену адресата. Объясните, почему выразительное чтение не должно превращаться в произвольное изменение авторской речи.'),('8-10','Описание традиции','Выберите главу «Лета Господня». Подготовьте монолог о традиции: её участники, действия, детали и личное отношение. Не приписывайте себе описанный в книге опыт.'),('5-10','Описание и наблюдение','Прочитайте одно стихотворение о природе, затем опишите собственное наблюдение прозой. Различите наблюдаемый признак и созданный поэтом образ.'),('6-14','Внимание к собеседнику','После «Ночи исцеления» обсудите, как понять потребность другого. В паре один задаёт уточняющие вопросы, другой отвечает с опорой на текст, не пересказывая всё произведение.')]
 for ref,title,text in items:body+=f'<section class="reading-list-entry"><h2>{title}</h2><p>{e(text)}</p><p>{link(ref)}</p></section>'
 body+='<h2>Связный монолог</h2><p>Для проекта 2027 года тренируем не менее 10 предложений в пределах 3 минут. Начните с темы, соедините 2–3 смысловых блока и завершите выводом. Важнее связь мыслей, чем механический подсчёт предложений. Попросите слушателя пересказать вашу основную мысль: если он её не понял, уточните переходы.</p><p><a href="/k-sochineniyu/sobesedovanie/">Учебный монолог, вопросы и поле для плана</a></p>'
 return body

def activities():
 return '<p>Эти занятия не имеют единого экзаменационного списка. Подборки составлены мастерской для разных возрастов. Конкретный конкурс, олимпиада или школа могут устанавливать собственный регламент; наш список не выдаётся за их программу.</p>'+''.join(f'<section class="reading-list-entry"><p class="eyebrow">{age}</p><h2>{title}</h2><p>{text}</p>{route_links(refs)}</section>' for age,title,text,refs in [
 ('1–4 классы','Семейный читательский дневник','После сказки или короткого рассказа ребёнок выбирает один поступок, рисует или описывает его и отвечает: что произошло и почему это важно? Взрослый записывает ответ со слов ребёнка, сохраняя его собственную мысль. Для старта — сказки, рассказы о животных и дружбе из соответствующего класса.',['1-2','2-4','3-4','4-4']),
 ('5–6 классы','Устная рекомендация книги','Подготовьте минутную рекомендацию «Снежной королевы», «Кавказского пленника» или «Чудесного доктора». Назовите вопрос, который поднимает книга, одну выразительную деталь и читателя, которому она может быть интересна. Не раскрывайте весь сюжет.',['5-19','5-9','6-12']),
 ('7–9 классы','Рецензия и читательская дискуссия','Сопоставьте «Станционного смотрителя» и «После бала»: как меняется понимание другого человека? В рецензии отделите краткое введение в книгу от своей оценки, подкреплённой двумя примерами. В дискуссии сначала точно передайте мысль оппонента.',['7-3','7-8','9-3']),
 ('8–11 классы','Литература, картина и музыка','Выберите произведение и одну работу из нашей галереи либо одну музыкальную запись. Установите общее основание сравнения: образ дома, разлуки, памяти, просьбы. Назовите также различие, которое нельзя устранить: музыка и картина не пересказывают автоматически литературный сюжет.',['9-9','11-11','8-10']),
 ('10–11 классы','Мини-исследование и полемическое эссе','Возьмите критическую статью и художественный текст, о котором она написана. Выпишите тезис критика, его доказательство и эпизод, допускающий уточнение. Затем напишите собственное рассуждение, в котором позиция оппонента узнаваема и не упрощена.',['10-14','10-2','10-3','10-4']),
 ])+'<p><a href="/iskusstvo/">Галерея человеческого искусства</a> · <a href="/muzyka/">Светская и церковная музыка</a> · <a href="/filosofiya/">Общие философские вопросы</a></p>'+spiritual()

def extras():
 body='<p>Эти позиции расширяют базовый курс. Для каждой указан объём работы: чтение произведения, разбор начала или карта проверки источника. Выбор «Рождества» для знакомства с прозой Набокова принадлежит мастерской. Отдельное название рассказа ФИПИ в этой позиции не устанавливает.</p>'
 for x in EXTRAS:
  body+=f'<section class="reading-list-entry" id="{x["id"]}"><p class="eyebrow">{e(x["scope"])}</p><h2>{e(x["title"])}</h2><p><a href="{x["source"]}">{e(x["label"])}</a></p>{paragraphs(x["paragraphs"])}'
  if x['quote']:body+=quote_block(x['quote'])
  body+=f'<h3>Комментарий мастерской</h3><p>{e(x["reflection"])}</p><p><strong>Самостоятельный ответ:</strong> {e(x["task"])}</p><p>Связанный разбор: {link(x["related"])}</p></section>'
 return body

def publish_reading_lists(page):
 rows='<tr><th><a href="/chtenie/vneklassnoe/">Внеклассное и факультативное чтение</a></th><td>Каталог 1–11 классов, 46 карточек по учебникам и отдельные разборы</td></tr>'+''.join(f'<tr><th><a href="{ROOT}{s}/">{t}</a></th><td>{d}</td></tr>' for s,t,d in SECTIONS)
 body='<p>Выберите цель чтения. Для экзаменов по литературе есть официальные перечни авторов и произведений. Для русского языка, итогового сочинения и речевой практики предлагаем собственные подборки с ясным объяснением, зачем читать каждую книгу.</p><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Для какой работы</th><th>Что внутри</th></tr></thead><tbody>'+rows+'</tbody></table></div><h2>Как список становится чтением</h2><ol><li>Проверьте статус: конкретное произведение, авторская группа или рекомендация мастерской.</li><li>Прочитайте произведение или обозначенные документом фрагменты.</li><li>Откройте связанный разбор. Выпишите эпизод, художественный приём и свой вывод.</li><li>Вернитесь к вопросу задания: материал должен доказывать именно ваш ответ.</li></ol><p>Перечни ФИПИ отражены полностью по позициям таблицы 3, но открытые группы не превращены в обещание разобрать каждую книгу каждого автора. Связанные занятия показывают реально подготовленные материалы.</p>'+spiritual()
 page(ROOT,'Что читать: списки и маршруты','Официальные перечни ОГЭ и ЕГЭ по литературе, рекомендации для русского языка, итогового сочинения и творческой практики.',shell('Что читать — и как с этим работать','От экзаменационного перечня к внимательному чтению и собственному ответу.',body),active='reading')
 builders={'oge-literatura':lambda:codifier('oge'),'ege-literatura':lambda:codifier('ege'),'russkiy-yazyk':russian_list,'itogovoe':final_list,'sobesedovanie':oral_list,'drugie-formy':activities,'dopolneniya':extras}
 paths=[ROOT]
 for slug,title,lead in SECTIONS:
  path=ROOT+slug+'/'
  page(path,title+' — что читать',lead,shell(title,lead,builders[slug]()),active='reading');paths.append(path)
 return paths


def references_for_unit(n, unit_id):
    ref=f"{n}-{int(unit_id.split('-')[1])}"
    data=json.loads(Path(__file__).with_name('reading_lists_data.json').read_text())
    links=[]
    for kind,rows in data.items():
        for r in rows:
            if ref in r['routes']:
                links.append(f'<a href="/chtenie/{kind}-literatura/#code-{r["code"]}">{"ЕГЭ" if kind=="ege" else "ОГЭ"}: код {r["code"]}</a>')
    if not links:return ''
    return '<section><h2>Связь с экзаменационными перечнями</h2><p>'+ ' · '.join(links)+'</p><p class="fine">Сопоставлены авторы и произведения. Учебный выбор в этом занятии может быть уже экзаменационной позиции: точный объём чтения указан по ссылке.</p></section>'
